// Generates packages/rules/src/se/localities-<year>.ts from SCB's open statistics database
// (table OE0101: Kommunala skattesatser + Begravningsavgift samt kyrkoavgift).
// Usage: node scripts/fetch-localities.mjs 2026
// Needs internet; the generated file is committed, the app itself never calls the network.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const year = process.argv[2];
if (!/^\d{4}$/.test(year ?? '')) {
  console.error('Usage: node scripts/fetch-localities.mjs <year>');
  process.exit(1);
}
const BASE = 'https://api.scb.se/OV0104/v1/doris/sv/ssd/OE/OE0101';

async function meta(table) {
  const res = await fetch(`${BASE}/${table}`);
  if (!res.ok) throw new Error(`${table}: HTTP ${res.status}`);
  return res.json();
}

async function query(table) {
  const body = {
    query: [
      { code: 'Region', selection: { filter: 'all', values: ['*'] } },
      { code: 'ContentsCode', selection: { filter: 'all', values: ['*'] } },
      { code: 'Tid', selection: { filter: 'item', values: [year] } },
    ],
    response: { format: 'json' },
  };
  const res = await fetch(`${BASE}/${table}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`${table}: HTTP ${res.status}`);
  // The API answers with a UTF-8 BOM.
  return JSON.parse((await res.text()).replace(/^[\uFEFF]/, ''));
}

const names = new Map();
for (const v of (await meta('Kommunalskatter2000')).variables) {
  if (v.code === 'Region') v.values.forEach((c, i) => names.set(c, v.valueTexts[i]));
}
const countyNames = new Map();
for (const v of (await meta('BegrochKyrkoavg2000')).variables) {
  if (v.code === 'Region') v.values.forEach((c, i) => countyNames.set(c, v.valueTexts[i]));
}

const tax = await query('Kommunalskatter2000');
const church = await query('BegrochKyrkoavg2000');
const num = (s) => {
  const n = Number(s);
  if (!Number.isFinite(n)) throw new Error(`Not a number: ${s}`);
  return n;
};

const municipalities = [];
let national;
for (const row of tax.data) {
  const code = row.key[0];
  const [total, municipal, regional] = row.values.map(num);
  if (code === '00') national = { total, municipal, regional };
  else if (code.length === 4) {
    municipalities.push({ code, name: names.get(code), county: code.slice(0, 2), total, municipal, regional });
  }
}
const counties = [];
let nationalChurch;
for (const row of church.data) {
  const code = row.key[0];
  const [burial, churchInclBurial] = row.values.map(num);
  if (code === '00') nationalChurch = { burial, churchInclBurial };
  else counties.push({ code, name: countyNames.get(code), burial, churchInclBurial });
}
municipalities.sort((a, b) => a.name.localeCompare(b.name, 'sv'));
if (municipalities.length < 280 || !national || !nationalChurch || counties.length !== 21) {
  throw new Error(`Unexpected data: ${municipalities.length} municipalities, ${counties.length} counties`);
}
for (const m of municipalities) {
  if (!m.name || !counties.some((c) => c.code === m.county)) throw new Error(`Bad row ${JSON.stringify(m)}`);
}

const q = (s) => JSON.stringify(s);
const lines = [];
lines.push(`import type { LocalityData } from '../localities';`);
lines.push('');
lines.push('/**');
lines.push(` * Local tax rates ${year}. GENERATED by scripts/fetch-localities.mjs from Statistics Sweden (SCB),`);
lines.push(' * table OE0101 (Kommunala skattesatser; Begravningsavgift samt kyrkoavgift). Do not edit by hand.');
lines.push(' * Rates are percent of taxable income. Church and burial fees are county averages (SCB does not');
lines.push(' * publish them per municipality; the exact parish rate is on the tax assessment notice).');
lines.push(' */');
lines.push(`export const LOCALITIES_${year}: LocalityData = {`);
lines.push(`  year: ${year},`);
lines.push(`  source: ${q(`Statistics Sweden (SCB), table OE0101, fetched ${new Date().toISOString().slice(0, 10)}`)},`);
lines.push(`  national: { totalPct: ${national.total}, burialPct: ${nationalChurch.burial}, churchInclBurialPct: ${nationalChurch.churchInclBurial} },`);
lines.push('  counties: [');
for (const c of counties) {
  lines.push(`    { code: ${q(c.code)}, name: ${q(c.name)}, burialPct: ${c.burial}, churchInclBurialPct: ${c.churchInclBurial} },`);
}
lines.push('  ],');
lines.push('  municipalities: [');
for (const m of municipalities) {
  lines.push(`    { code: ${q(m.code)}, name: ${q(m.name)}, county: ${q(m.county)}, totalPct: ${m.total}, municipalPct: ${m.municipal}, regionalPct: ${m.regional} },`);
}
lines.push('  ],');
lines.push('};');
lines.push('');

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, '..', 'packages', 'rules', 'src', 'se', `localities-${year}.ts`);
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out}: ${municipalities.length} municipalities, ${counties.length} counties`);
